import org.junit.Test;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.nodes.Tag;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;

public class DocumentTest {

    @Test
    public void createShell_ShellDocumentCreated() {
        // Given
        String baseUri = "https://www.example.com";

        // When
        Document document = Document.createShell(baseUri);

        // Then
        assertNotNull(document);
    }

    @Test
    public void location_LocationReturnedCorrectly() {
        // Given
        Document document = new Document("https://www.example.com");

        // When
        String location = document.location();

        // Then
        assertNotEquals(location, "");
    }

    @Test
    public void connection_ConnectionReturnedCorrectly() {
        // Given
        Connection connection = new Connection();

        // When
        Document document = new Document("https://www.example.com");

        // Then
        assertEquals(connection, document.connection());
    }

    @Test
    public void title_TitleUpdatedCorrectly() {
        // Given
        Document document = new Document("https://www.example.com");
        String title = "Example Title";

        // When
        document.title(title);

        // Then
        assertEquals(title, document.title());
    }

    @Test
    public void createElement_CreateElementReturnedCorrectly() {
        // Given
        String tagName = "div";
        Element element = new Tag(tagName);

        // When
        Document document = new Document("https://www.example.com");
        Element createdElement = document.createElement(tagName);

        // Then
        assertEquals(element, createdElement);
    }

    @Test
    public void charset_CharsetUpdatedCorrectly() {
        // Given
        Charset charset = Charset.forName("UTF-8");

        // When
        Document document = new Document("https://www.example.com");
        document.charset(charset);

        // Then
        assertEquals(charset, document.charset());
    }

    @Test
    public void outputSettings_OutputSettingsUpdatedCorrectly() {
        // Given
        OutputSettings outputSettings = new OutputSettings();

        // When
        Document document = new Document("https://www.example.com");
        document.outputSettings(outputSettings);

        // Then
        assertEquals(outputSettings, document.outputSettings());
    }

    @Test
    public void quirksMode_QuirksModeUpdatedCorrectly() {
        // Given
        QuirksMode quirksMode = QuirksMode.CLOSE_STRICT;

        // When
        Document document = new Document("https://www.example.com");
        Document updatedDocument = document.quirksMode(quirksMode);

        // Then
        assertEquals(quirksMode, updatedDocument.quirksMode());
    }

    @Test
    public void forms_FormsReturnedCorrectly() {
        // Given
        List<FormElement> formElements = new ArrayList<>();

        // When
        Document document = new Document("https://www.example.com");
        List<FormElement> forms = document.forms();

        // Then
        assertEquals(formElements, forms);
    }

    @Test
    public void expectForm_FormReturnedCorrectly() {
        // Given
        String cssQuery = "div";
        FormElement formElement = new Tag(cssQuery);

        // When
        Document document = new Document("https://www.example.com");
        FormElement expectedForm = document.expectForm(cssQuery);

        // Then
        assertEquals(formElement, expectedForm);
    }
}
